<?php
namespace App\Services\Face;use App\Contracts\FaceProvider;
class FakeFaceProvider implements FaceProvider {private static array$collections=[];public function resolveCollection(string$key):string{self::$collections[$key]??=[];return$key;}public function indexFace(string$c,string$external,string$bytes):array{$id=hash('sha256',$c.'|'.$external);self::$collections[$c][$id]=['external_id'=>$external,'hash'=>hash('sha256',$bytes)];return['face_id'=>$id,'confidence'=>100.0];}public function search(string$c,string$bytes,float$t,int$max):array{$configured=config('face.fake_matches');$rows=is_array($configured)?$configured:array_map(fn($v)=>['external_id'=>$v['external_id'],'face_id'=>$v['face_id'],'similarity'=>$v['hash']===hash('sha256',$bytes)?99.9:95.0],self::$collections[$c]??[]);return array_slice(array_values(array_filter($rows,fn($r)=>(float)$r['similarity']>=$t)),0,$max);}public function removeFaces(string$c,array$ids):void{foreach($ids as$id)unset(self::$collections[$c][$id]);}public function deleteCollection(string$c):void{unset(self::$collections[$c]);}public function health():array{return['healthy'=>true,'provider'=>'fake'];}public static function reset():void{self::$collections=[];}}
